    28	public final class App {
    29	    private static final ObjectMapper JSON = new ObjectMapper()
    30	            .enable(SerializationFeature.WRITE_BIGDECIMAL_AS_PLAIN)
    31	            .setNodeFactory(JsonNodeFactory.withExactBigDecimals(true)); // 0.00 e não 0
    32	
    33	    private App() {}
    34	
    35	    public static Javalin create(Store store, BigDecimal tourismTaxPerGuestNight) {
    36	        ReservationService service = new ReservationService(store);
    37	        Reports reports = new Reports(store, tourismTaxPerGuestNight);
    38	
    39	        Javalin app = Javalin.create(cfg -> cfg.showJavalinBanner = false);
    40	
    41	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status(), e.code(), e.getMessage()));
    42	        app.exception(Exception.class, (e, ctx) -> {
    43	            e.printStackTrace();
    44	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
    45	        });
    46	        app.error(404, ctx -> {
    47	            String type = ctx.res().getContentType();
    48	            if (type == null || !type.startsWith("application/json")) {
    49	                error(ctx, 404, "NOT_FOUND", "Recurso não encontrado");
    50	            }
    51	        });
    52	
    53	        app.get("/rooms", ctx -> {
    54	            ArrayNode arr = JSON.createArrayNode();
    55	            for (Room r : Room.ALL) {
    56	                arr.add(JSON.createObjectNode().put("number", r.number()).put("type", r.type().name())
    57	                        .put("capacity", r.capacity()).put("nightlyRate", r.nightlyRate()));
    58	            }
    59	            json(ctx, 200, arr);
    60	        });
    61	
    62	        app.post("/reservations", ctx -> json(ctx, 201, reservation(service.create(parseNew(ctx)))));
    63	        app.get("/reservations/{id}", ctx -> json(ctx, 200, reservation(service.get(ctx.pathParam("id")))));
    64	        action(app, "confirmation", service::confirm);
    65	        action(app, "cancellation", service::cancel);
    66	        action(app, "check-in", service::checkIn);
    67	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, receipt(service.checkOut(ctx.pathParam("id")))));
    68	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, receipt(service.document(ctx.pathParam("id")))));
    69	
    70	        app.get("/messages", ctx -> {
    71	            ArrayNode arr = JSON.createArrayNode();
    72	            for (Message m : service.messages()) {
    73	                arr.add(JSON.createObjectNode().put("id", m.id()).put("channel", m.channel()).put("to", m.to())
    74	                        .put("subject", m.subject()).put("body", m.body()));
    75	            }
    76	            json(ctx, 200, arr);
    77	        });
    78	
    79	        for (ReportType type : reports.types()) {
    80	            app.get("/reports/" + type.name(), ctx -> {
    81	                String csv = reports.csv(type, ctx.queryParam(type.periodParam()));
    82	                ctx.contentType("text/csv; charset=utf-8").result(csv);
    83	            });
    84	        }
    85	        return app;
    86	    }
