     3	public class ApiException extends RuntimeException {
     4	    private final int status;
     5	    private final String code;
     6	
     7	    public ApiException(int status, String code, String message) {
     8	        super(message);
     9	        this.status = status;
    10	        this.code = code;
    11	    }
    12	
    13	    public int status() { return status; }
    14	    public String code() { return code; }
    15	
    16	    public static ApiException invalid(String message) { return new ApiException(400, "INVALID_REQUEST", message); }
    17	    public static ApiException roomNotFound(int n) { return new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + n + " não existe"); }
    18	    public static ApiException reservationNotFound(String id) { return new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe"); }
    19	    public static ApiException roomUnavailable() { return new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites"); }
    20	    public static ApiException notAllowed(String message) { return new ApiException(409, "OPERATION_NOT_ALLOWED", message); }
    21	    public static ApiException capacityExceeded(int capacity) { return new ApiException(422, "CAPACITY_EXCEEDED", "O quarto comporta no máximo " + capacity + " hóspede(s)"); }
    22	}
