    88	    private static void action(Javalin app, String path, Function<String, Reservation> op) {
    89	        app.post("/reservations/{id}/" + path, ctx -> json(ctx, 200, reservation(op.apply(ctx.pathParam("id")))));
    90	    }
    91	
    92	    // ---- entrada ----
    93	
    94	    private static NewReservation parseNew(Context ctx) {
    95	        JsonNode body;
    96	        try {
    97	            body = JSON.readTree(ctx.bodyAsBytes());
    98	        } catch (java.io.IOException e) {
    99	            throw ApiException.invalid("O corpo deve ser um JSON válido");
   100	        }
   101	        if (body == null || !body.isObject()) throw ApiException.invalid("O corpo deve ser um objeto JSON");
   102	        return new NewReservation(
   103	                integer(body, "roomNumber"),
   104	                text(body, "guestName"), text(body, "guestEmail"), text(body, "guestCpf"),
   105	                date(body, "checkIn"), date(body, "checkOut"),
   106	                integer(body, "guests"),
   107	                ratePlan(body));
   108	    }
   109	
   110	    private static String text(JsonNode body, String field) {
   111	        JsonNode n = body.get(field);
   112	        if (n == null || !n.isTextual() || n.asText().isBlank()) {
   113	            throw ApiException.invalid("Campo obrigatório ausente ou inválido: " + field);
   114	        }
   115	        return n.asText().strip();
   116	    }
   117	
   118	    private static int integer(JsonNode body, String field) {
   119	        JsonNode n = body.get(field);
   120	        if (n == null || !n.isIntegralNumber() || !n.canConvertToInt()) {
   121	            throw ApiException.invalid("Campo obrigatório ausente ou inválido: " + field);
   122	        }
   123	        return n.intValue();
   124	    }
   125	
   126	    private static LocalDate date(JsonNode body, String field) {
   127	        String s = text(body, field);
   128	        try {
   129	            if (!s.matches("\\d{4}-\\d{2}-\\d{2}")) throw new IllegalArgumentException();
   130	            return LocalDate.parse(s);
   131	        } catch (RuntimeException e) {
   132	            throw ApiException.invalid("Data inválida em " + field + " (use 2027-07-10)");
   133	        }
   134	    }
   135	
   136	    private static RatePlan ratePlan(JsonNode body) {
   137	        String s = text(body, "ratePlan");
   138	        try {
   139	            return RatePlan.valueOf(s);
   140	        } catch (IllegalArgumentException e) {
   141	            throw ApiException.invalid("ratePlan deve ser STANDARD ou NON_REFUNDABLE");
   142	        }
   143	    }
   144	
   145	    // ---- saída ----
   146	
   147	    private static ObjectNode reservation(Reservation r) {
   148	        ObjectNode o = JSON.createObjectNode();
   149	        o.put("id", r.id()).put("roomNumber", r.roomNumber()).put("guestName", r.guestName())
   150	                .put("guestEmail", r.guestEmail()).put("guestCpf", r.guestCpf())
   151	                .put("checkIn", r.checkIn().toString()).put("checkOut", r.checkOut().toString())
   152	                .put("guests", r.guests()).put("ratePlan", r.ratePlan().name()).put("nights", r.nights())
   153	                .put("subtotal", r.subtotal()).put("discount", r.discount()).put("total", r.total())
   154	                .put("status", r.status().name()).put("amountPaid", r.amountPaid());
   155	        if (r.refund() == null) o.putNull("refund"); else o.put("refund", r.refund());
   156	        return o;
   157	    }
   158	
   159	    private static ObjectNode receipt(Receipt d) {
   160	        return JSON.createObjectNode().put("title", Receipt.TITLE).put("reservationId", d.reservationId())
   161	                .put("guestName", d.guestName()).put("guestCpf", d.guestCpf()).put("roomNumber", d.roomNumber())
   162	                .put("roomType", d.roomType().name()).put("checkIn", d.checkIn().toString())
   163	                .put("checkOut", d.checkOut().toString()).put("nights", d.nights())
   164	                .put("subtotal", d.subtotal()).put("discount", d.discount()).put("total", d.total());
   165	    }
   166	
   167	    private static void json(Context ctx, int status, JsonNode node) {
   168	        try {
   169	            ctx.status(status).contentType("application/json").result(JSON.writeValueAsString(node));
   170	        } catch (JsonProcessingException e) {
   171	            throw new IllegalStateException(e);
   172	        }
   173	    }
   174	
   175	    private static void error(Context ctx, int status, String code, String message) {
   176	        json(ctx, status, JSON.createObjectNode().put("error", code).put("message", message));
   177	    }
   178	}
