    16	public class ReservationService {
    17	
    18	    public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    19	                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {}
    20	
    21	    private final Store store;
    22	
    23	    public ReservationService(Store store) {
    24	        this.store = store;
    25	    }
    26	
    27	    public Reservation create(NewReservation n) {
    28	        if (!n.checkOut().isAfter(n.checkIn())) throw ApiException.invalid("A saída deve ser depois da entrada");
    29	        if (n.guests() < 1) throw ApiException.invalid("É preciso ao menos 1 hóspede");
    30	        Room room = Room.find(n.roomNumber()).orElseThrow(() -> ApiException.roomNotFound(n.roomNumber()));
    31	        if (n.guests() > room.capacity()) throw ApiException.capacityExceeded(room.capacity());
    32	
    33	        Pricing.Quote q = Pricing.quote(room.type(), n.checkIn(), n.checkOut(), n.ratePlan());
    34	        return store.inTransaction(tx -> {
    35	            tx.lockRoom(room.number());
    36	            if (tx.hasOverlap(room.number(), n.checkIn(), n.checkOut())) throw ApiException.roomUnavailable();
    37	            return tx.insert(new Reservation(0, room.number(), n.guestName(), n.guestEmail(), n.guestCpf(),
    38	                    n.checkIn(), n.checkOut(), n.guests(), n.ratePlan(), q.nights(), q.subtotal(), q.discount(),
    39	                    q.total(), Status.PENDING, Money.ZERO, null));
    40	        });
    41	    }
    42	
    43	    public Reservation get(String id) {
    44	        return store.inTransaction(tx -> tx.find(parseId(id)).orElseThrow(() -> ApiException.reservationNotFound(id)));
    45	    }
    46	
    47	    /** Confirma (pagamento do total) e guarda o e-mail de confirmação na mesma transação. */
    48	    public Reservation confirm(String id) {
    49	        return store.inTransaction(tx -> {
    50	            Reservation r = lock(tx, id);
    51	            require(r, "confirmar", Status.PENDING);
    52	            Reservation confirmed = r.withStatus(Status.CONFIRMED).withPayment(r.total());
    53	            tx.update(confirmed);
    54	            tx.addMessage(Mailer.CHANNEL, confirmed.guestEmail(), Mailer.CONFIRMATION_SUBJECT,
    55	                    Mailer.confirmationBody(confirmed));
    56	            return confirmed;
    57	        });
    58	    }
    59	
    60	    public Reservation cancel(String id) {
    61	        return store.inTransaction(tx -> {
    62	            Reservation r = lock(tx, id);
    63	            require(r, "cancelar", Status.PENDING, Status.CONFIRMED);
    64	            boolean refunds = r.status() == Status.CONFIRMED && r.ratePlan().refundable();
    65	            Reservation cancelled = r.withStatus(Status.CANCELLED)
    66	                    .withRefund(refunds ? r.amountPaid() : Money.ZERO);
    67	            tx.update(cancelled);
    68	            return cancelled;
    69	        });
    70	    }
    71	
    72	    public Reservation checkIn(String id) {
    73	        return store.inTransaction(tx -> {
    74	            Reservation r = lock(tx, id);
    75	            require(r, "fazer check-in de", Status.CONFIRMED);
    76	            Reservation updated = r.withStatus(Status.CHECKED_IN);
    77	            tx.update(updated);
    78	            return updated;
    79	        });
    80	    }
    81	
    82	    public Receipt checkOut(String id) {
    83	        return store.inTransaction(tx -> {
    84	            Reservation r = lock(tx, id);
    85	            require(r, "fazer check-out de", Status.CHECKED_IN);
    86	            Reservation updated = r.withStatus(Status.CHECKED_OUT);
    87	            tx.update(updated);
    88	            return Receipt.of(updated);
    89	        });
    90	    }
    91	
    92	    /** Segunda via: só para reserva paga. */
    93	    public Receipt document(String id) {
    94	        Reservation r = get(id);
    95	        if (!r.status().isPaid()) {
    96	            throw ApiException.notAllowed("Só há comprovante para reserva paga (situação atual: " + r.status() + ")");
    97	        }
    98	        return Receipt.of(r);
    99	    }
   100	
   101	    public List<Message> messages() {
