    12	    public static String toCsv(Report report) {
    13	        StringBuilder sb = new StringBuilder();
    14	        line(sb, List.of(ESTABLISHMENT, report.name(), report.period()));
    15	        line(sb, report.header());
    16	        report.rows().forEach(row -> line(sb, row));
    17	        line(sb, report.total());
    18	        return sb.toString();
    19	    }
    20	
    21	    private static void line(StringBuilder sb, List<String> fields) {
    22	        sb.append(fields.stream().map(ReportWriter::escape).collect(Collectors.joining(","))).append('\n');
    23	    }
    24	
    25	    private static String escape(String f) {
    26	        if (f.contains(",") || f.contains("\"") || f.contains("\n") || f.contains("\r")) {
