     9	import java.util.ArrayList;
    10	import java.util.Comparator;
    11	import java.util.List;
    12	import java.util.Optional;
    13	import java.util.TreeMap;
    14	import java.util.function.Function;
    15	
    16	/** Implementação em memória (testes). Uma transação por vez. */
    17	public class InMemoryStore implements Store {
    18	    private final TreeMap<Long, Reservation> reservations = new TreeMap<>();
    19	    private final List<Message> messages = new ArrayList<>();
    20	
    21	    @Override
    22	    public synchronized <T> T inTransaction(Function<Tx, T> work) {
    23	        return work.apply(new MemTx());
    24	    }
    25	
    26	    private class MemTx implements Tx {
    27	        @Override public void lockRoom(int roomNumber) {}
    28	
    29	        @Override
    30	        public boolean hasOverlap(int room, LocalDate in, LocalDate out) {
    31	            return reservations.values().stream().anyMatch(r -> r.roomNumber() == room
    32	                    && r.status() != Status.CANCELLED
    33	                    && r.checkIn().isBefore(out) && in.isBefore(r.checkOut()));
    34	        }
    35	
    36	        @Override
    37	        public Reservation insert(Reservation draft) {
    38	            Reservation saved = draft.withId(reservations.isEmpty() ? 1 : reservations.lastKey() + 1);
    39	            reservations.put(saved.id(), saved);
    40	            return saved;
    41	        }
    42	
    43	        @Override public Optional<Reservation> findForUpdate(long id) { return find(id); }
    44	
    45	        @Override public Optional<Reservation> find(long id) { return Optional.ofNullable(reservations.get(id)); }
    46	
    47	        @Override public void update(Reservation r) { reservations.put(r.id(), r); }
    48	
    49	        @Override
    50	        public List<Reservation> startingIn(YearMonth month) {
    51	            return reservations.values().stream()
    52	                    .filter(r -> YearMonth.from(r.checkIn()).equals(month))
    53	                    .sorted(Comparator.comparing(Reservation::checkIn).thenComparing(Reservation::id))
    54	                    .toList();
    55	        }
    56	
    57	        @Override
    58	        public List<Reservation> paidOccupying(LocalDate night) {
    59	            return reservations.values().stream()
    60	                    .filter(r -> r.status().isPaid() && !r.checkIn().isAfter(night) && night.isBefore(r.checkOut()))
    61	                    .sorted(Comparator.comparing(Reservation::roomNumber).thenComparing(Reservation::id))
    62	                    .toList();
    63	        }
    64	
    65	        @Override
    66	        public Message addMessage(String channel, String to, String subject, String body) {
    67	            Message m = new Message(messages.size() + 1L, channel, to, subject, body);
    68	            messages.add(m);
    69	            return m;
    70	        }
    71	
    72	        @Override public List<Message> messages() { return List.copyOf(messages); }
    73	    }
    74	}
