    23	public class PostgresStore implements Store, AutoCloseable {
    24	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    25	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
