    29	    public PostgresStore(String url, String user, String password) {
    30	        HikariConfig cfg = new HikariConfig();
    31	        cfg.setJdbcUrl(url);
    32	        cfg.setUsername(user);
    33	        cfg.setPassword(password);
    34	        cfg.setMaximumPoolSize(10);
    35	        cfg.setInitializationFailTimeout(-1); // o banco pode demorar a subir; tentamos nós mesmos
    36	        this.ds = new HikariDataSource(cfg);
