    38	
    39	    /** Cria o que falta no banco, esperando-o ficar disponível por até {@code waitMillis}. */
    40	    public void initSchema(long waitMillis) {
    41	        long deadline = System.currentTimeMillis() + waitMillis;
    42	        while (true) {
    43	            try (Connection c = ds.getConnection(); Statement st = c.createStatement()) {
    44	                c.setAutoCommit(false);
    45	                st.execute("SELECT pg_advisory_xact_lock(7070)"); // várias instâncias subindo juntas
    46	                st.execute("""
    47	                        CREATE TABLE IF NOT EXISTS reservations (
    48	                            id BIGSERIAL PRIMARY KEY,
    49	                            room_number INT NOT NULL,
    50	                            guest_name TEXT NOT NULL,
    51	                            guest_email TEXT NOT NULL,
    52	                            guest_cpf TEXT NOT NULL,
    53	                            check_in DATE NOT NULL,
    54	                            check_out DATE NOT NULL,
    55	                            guests INT NOT NULL,
    56	                            rate_plan TEXT NOT NULL,
    57	                            nights INT NOT NULL,
    58	                            subtotal NUMERIC(12,2) NOT NULL,
    59	                            discount NUMERIC(12,2) NOT NULL,
    60	                            total NUMERIC(12,2) NOT NULL,
    61	                            status TEXT NOT NULL,
    62	                            amount_paid NUMERIC(12,2) NOT NULL,
    63	                            refund NUMERIC(12,2)
    64	                        )""");
    65	                st.execute("CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations (room_number, check_in)");
    66	                st.execute("CREATE INDEX IF NOT EXISTS reservations_check_in_idx ON reservations (check_in, id)");
    67	                st.execute("""
    68	                        CREATE TABLE IF NOT EXISTS messages (
    69	                            id BIGSERIAL PRIMARY KEY,
    70	                            channel TEXT NOT NULL,
    71	                            recipient TEXT NOT NULL,
    72	                            subject TEXT NOT NULL,
    73	                            body TEXT NOT NULL
    74	                        )""");
    75	                c.commit();
    76	                return;
    77	            } catch (SQLException e) {
    78	                if (System.currentTimeMillis() > deadline) throw new IllegalStateException("Banco indisponível", e);
    79	                try {
    80	                    Thread.sleep(1000);
    81	                } catch (InterruptedException ie) {
    82	                    Thread.currentThread().interrupt();
    83	                    throw new IllegalStateException(ie);
    84	                }
    85	            }
    86	        }
    87	    }
    88	
    89	    @Override
    90	    public <T> T inTransaction(Function<Tx, T> work) {
    91	        try (Connection c = ds.getConnection()) {
    92	            c.setAutoCommit(false);
    93	            try {
    94	                T result = work.apply(new PgTx(c));
    95	                c.commit();
