    16	/** Implementação em memória (testes). Uma transação por vez. */
    17	public class InMemoryStore implements Store {
    18	    private final TreeMap<Long, Reservation> reservations = new TreeMap<>();
    19	    private final List<Message> messages = new ArrayList<>();
    20	
    21	    @Override
    22	    public synchronized <T> T inTransaction(Function<Tx, T> work) {
    23	        return work.apply(new MemTx());
    24	    }
    25	
    26	    private class MemTx implements Tx {
    27	        @Override public void lockRoom(int roomNumber) {}
    28	
    29	        @Override
    30	        public boolean hasOverlap(int room, LocalDate in, LocalDate out) {
    31	            return reservations.values().stream().anyMatch(r -> r.roomNumber() == room
    32	                    && r.status() != Status.CANCELLED
    33	                    && r.checkIn().isBefore(out) && in.isBefore(r.checkOut()));
    34	        }
    35	
    36	        @Override
    37	        public Reservation insert(Reservation draft) {
    38	            Reservation saved = draft.withId(reservations.isEmpty() ? 1 : reservations.lastKey() + 1);
    39	            reservations.put(saved.id(), saved);
    40	            return saved;
    41	        }
    42	
    43	        @Override public Optional<Reservation> findForUpdate(long id) { return find(id); }
    44	
    45	        @Override public Optional<Reservation> find(long id) { return Optional.ofNullable(reservations.get(id)); }
    46	
    47	        @Override public void update(Reservation r) { reservations.put(r.id(), r); }
