    49	        @Override
    50	        public List<Reservation> startingIn(YearMonth month) {
    51	            return reservations.values().stream()
    52	                    .filter(r -> YearMonth.from(r.checkIn()).equals(month))
    53	                    .sorted(Comparator.comparing(Reservation::checkIn).thenComparing(Reservation::id))
    54	                    .toList();
    55	        }
    56	
    57	        @Override
    58	        public List<Reservation> paidOccupying(LocalDate night) {
    59	            return reservations.values().stream()
    60	                    .filter(r -> r.status().isPaid() && !r.checkIn().isAfter(night) && night.isBefore(r.checkOut()))
    61	                    .sorted(Comparator.comparing(Reservation::roomNumber).thenComparing(Reservation::id))
    62	                    .toList();
    63	        }
