242	/** Repete os testes da API contra um PostgreSQL de verdade, num schema descartável. */
243	@EnabledIfEnvironmentVariable(named = "DB_URL", matches = "jdbc:postgresql:.*")
244	class PostgresApiTest extends ApiTest {
245	    private final String schema = "test_" + UUID.randomUUID().toString().replace("-", "");
246	    private PostgresStore pg;
247	
248	    @Override
249	    protected Store newStore() {
250	        String url = System.getenv("DB_URL");
251	        String user = System.getenv("DB_USER");
252	        String pass = System.getenv("DB_PASSWORD");
253	        try (Connection c = DriverManager.getConnection(url, user, pass); Statement st = c.createStatement()) {
254	            st.execute("CREATE SCHEMA " + schema);
255	        } catch (Exception e) {
256	            throw new IllegalStateException(e);
257	        }
258	        String sep = url.contains("?") ? "&" : "?";
259	        pg = new PostgresStore(url + sep + "currentSchema=" + schema, user, pass);
260	        pg.initSchema(10_000);
261	        return pg;
262	    }
263	
264	    @AfterEach
265	    void drop() throws Exception {
266	        pg.close();
267	        try (Connection c = DriverManager.getConnection(System.getenv("DB_URL"), System.getenv("DB_USER"),
268	                System.getenv("DB_PASSWORD")); Statement st = c.createStatement()) {
269	            st.execute("DROP SCHEMA " + schema + " CASCADE");
270	        }
271	    }
272	}
