242	/** Repete os testes da API contra um PostgreSQL de verdade, num schema descartável. */
243	@EnabledIfEnvironmentVariable(named = "DB_URL", matches = "jdbc:postgresql:.*")
244	class PostgresApiTest extends ApiTest {
